"""SQLite/PostgreSQL namespace-scoped logical change journal and restoration.

Only library-owned logical tables participate. No checkpoint, metadata,
credentials, extraction lease, vector payload or connection state is exported.
SQL names come from local schema introspection and a closed table allowlist.
"""

from __future__ import annotations

import json
from collections.abc import Iterator, Sequence
from contextlib import contextmanager
from datetime import datetime
from typing import Any

from octop_memory.operations.sync import MemoryChange, MemoryChanges

TABLE_KEYS: dict[str, tuple[str, ...]] = {
    "entities": ("id",),
    "raw_events": ("id",),
    "candidates": ("id",),
    "atoms": ("id",),
    "memory_nodes": ("id",),
    "aliases": ("alias", "entity_id"),
    "entity_pages": ("id",),
    "thread_active_entities": ("thread_id", "entity_id"),
    "episodes": ("id",),
    "digests": ("id",),
    "journal": ("id",),
}
JSON_COLUMNS = {
    "payload",
    "metadata",
    "raw_event_ids",
    "aliases",
    "search_terms",
    "topics",
    "people",
    "digest_ids",
    "episode_ids",
    "before",
    "after",
}


class LogicalSync:
    def __init__(self, backend: Any) -> None:
        from octop_memory.storage.backends.sqlite import SqliteMemoryBackend

        self.backend = backend
        self.sqlite = isinstance(backend, SqliteMemoryBackend)
        if not self.sqlite:
            from octop_memory.storage.backends.postgres import PostgresMemoryBackend

            if not isinstance(backend, PostgresMemoryBackend):
                raise NotImplementedError("logical synchronization requires SQLite or PostgreSQL")
        self.ns: str = backend._ns

    def name(self, table: str) -> str:
        return f'"{self.ns}_{table}"' if self.sqlite else f'"{table}"'

    @contextmanager
    def transaction(self, *, snapshot: bool = False) -> Iterator[Any]:
        nested = self.backend._in_transaction
        if snapshot and nested and not self.sqlite:
            raise ValueError("capture requires its own PostgreSQL snapshot transaction")
        with self.backend.transaction():
            if self.sqlite:
                yield self.backend._conn
            else:
                with self.backend._cursor() as cur:
                    if snapshot:
                        cur.execute("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ")
                    # Serialize namespace snapshots/restores across independent
                    # backend instances. Logical writers use row/table locks too.
                    cur.execute("SELECT pg_advisory_xact_lock(hashtext(%s))", ("logical-sync:" + self.ns,))
                    cur.execute("SET CONSTRAINTS ALL DEFERRED")
                    yield cur

    def execute(self, db: Any, sql: str, args: Sequence[Any] = ()) -> Any:
        result = db.execute(sql if self.sqlite else sql.replace("?", "%s"), args)
        return result if self.sqlite else db

    def init(self, db: Any) -> None:
        # Lazy, additive protocol tables: old readers and writers remain valid.
        identity = (
            "INTEGER PRIMARY KEY AUTOINCREMENT"
            if self.sqlite
            else "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY"
        )
        scope = "" if self.sqlite else "namespace TEXT NOT NULL,"
        key = "" if self.sqlite else "namespace,"
        self.execute(
            db,
            f"CREATE TABLE IF NOT EXISTS {self.name('sync_rows')} ({scope} table_name TEXT NOT NULL, "
            "row_key TEXT NOT NULL, revision BIGINT NOT NULL, data TEXT NOT NULL, "
            f"PRIMARY KEY({key}table_name,row_key))",
        )
        self.execute(
            db,
            f"CREATE TABLE IF NOT EXISTS {self.name('sync_changes')} (cursor {identity}, {scope} "
            "table_name TEXT NOT NULL, row_key TEXT NOT NULL, revision BIGINT NOT NULL, data TEXT NOT NULL)",
        )

    def scope(self, *, extra: bool = False) -> tuple[str, tuple[str, ...]]:
        return ("" if not extra else " WHERE 1=1", ()) if self.sqlite else (" WHERE namespace=?", (self.ns,))

    def columns(self, db: Any, table: str) -> list[str]:
        if self.sqlite:
            return [str(row["name"]) for row in self.execute(db, f"PRAGMA table_info({self.name(table)})").fetchall()]
        return [
            str(row["column_name"])
            for row in self.execute(
                db,
                "SELECT column_name FROM information_schema.columns WHERE table_schema='octop_memory' "
                "AND table_name=? AND is_generated='NEVER' AND column_name<>'namespace' ORDER BY ordinal_position",
                (table,),
            ).fetchall()
        ]

    @staticmethod
    def canonical(row: dict[str, Any]) -> str:
        values: dict[str, Any] = {}
        for key, raw_value in row.items():
            value = raw_value
            if key == "namespace" or key.endswith("_tsv"):
                continue
            if key in JSON_COLUMNS and value is not None:
                value = json.loads(value) if isinstance(value, str) else value
                value = json.dumps(value, sort_keys=True, ensure_ascii=False)
            elif isinstance(value, datetime):
                value = value.isoformat()
            elif isinstance(value, bool):
                value = int(value)
            values[key] = value
        return json.dumps(values, sort_keys=True, ensure_ascii=False)

    def _save(self, db: Any, table: str, key: str, revision: int, data: str) -> None:
        scope = () if self.sqlite else (self.ns,)
        prefix, conflict = ("", "") if self.sqlite else ("namespace,", "namespace,")
        placeholders = ",".join("?" for _ in range(len(scope) + 4))
        self.execute(
            db,
            f"INSERT INTO {self.name('sync_rows')} ({prefix}table_name,row_key,revision,data) "
            f"VALUES ({placeholders}) ON CONFLICT({conflict}table_name,row_key) "
            "DO UPDATE SET revision=excluded.revision,data=excluded.data",
            (*scope, table, key, revision, data),
        )
        self.execute(
            db,
            f"INSERT INTO {self.name('sync_changes')} ({prefix}table_name,row_key,revision,data) "
            f"VALUES ({placeholders})",
            (*scope, table, key, revision, data),
        )

    def changes(self, cursor: int, limit: int) -> MemoryChanges:
        if self.sqlite:
            return self._changes(cursor, limit)
        from psycopg.errors import SerializationFailure

        for attempt in range(3):
            try:
                return self._changes(cursor, limit)
            except SerializationFailure:
                if attempt == 2:
                    raise
        raise AssertionError("unreachable")

    def _changes(self, cursor: int, limit: int) -> MemoryChanges:
        if cursor < 0 or not 1 <= limit <= 1000:
            raise ValueError("invalid memory cursor or page size")
        with self.transaction(snapshot=True) as db:
            self.init(db)
            clause, args = self.scope()
            previous = {
                (row["table_name"], row["row_key"]): dict(row)
                for row in self.execute(db, f"SELECT * FROM {self.name('sync_rows')}{clause}", args).fetchall()
            }
            present: set[tuple[str, str]] = set()
            for table, keys in TABLE_KEYS.items():
                for raw in self.execute(
                    db, f"SELECT * FROM {self.name(table)}{clause} ORDER BY {','.join(keys)}", args
                ).fetchall():
                    row = dict(raw)
                    key = json.dumps([str(row[k]) for k in keys], ensure_ascii=False)
                    data = self.canonical(row)
                    present.add((table, key))
                    old = previous.get((table, key))
                    if not old or old["data"] != data:
                        self._save(db, table, key, int(old["revision"]) + 1 if old else 1, data)
            for (table, key), old in previous.items():
                if (table, key) not in present and old["data"] != "null":
                    self._save(db, table, key, int(old["revision"]) + 1, "null")
            clause, args = self.scope(extra=True)
            rows = self.execute(
                db,
                f"SELECT * FROM {self.name('sync_changes')}{clause} AND cursor>? ORDER BY cursor LIMIT ?",
                (*args, cursor, limit + 1),
            ).fetchall()
            result = [
                MemoryChange(
                    int(row["cursor"]),
                    row["table_name"],
                    json.loads(row["row_key"]),
                    int(row["revision"]),
                    json.loads(row["data"]),
                )
                for row in rows[:limit]
            ]
            return MemoryChanges(result[-1].cursor if result else cursor, len(rows) > limit, result)

    def restore(self, changes: Sequence[MemoryChange]) -> None:
        """Validate all rows before atomically applying. Host must pause writers.

        Restoring only logical records preserves live checkpoint tables. SQLite
        FTS is rebuilt transactionally; PostgreSQL generated tsvectors update
        with each row. Custom vector indexes require separate host rebuilding.
        """
        with self.transaction() as db:
            self.init(db)
            columns = {table: self.columns(db, table) for table in TABLE_KEYS}
            for change in changes:
                if (
                    change.table not in TABLE_KEYS
                    or len(change.key) != len(TABLE_KEYS[change.table])
                    or change.revision < 1
                ):
                    raise ValueError("invalid logical memory record")
                if change.data is not None and (
                    set(change.data) != set(columns[change.table])
                    or [str(change.data[k]) for k in TABLE_KEYS[change.table]] != change.key
                ):
                    raise ValueError("memory schema or primary key mismatch")
            # Defer the sole parent FK by applying parent-first nodes below;
            # PostgreSQL already defers all relational constraints.
            for change in changes:
                table = change.table
                keys = TABLE_KEYS[table]
                scope, scope_args = self.scope(extra=True)
                if change.data is None:
                    where = " AND ".join(f'"{key}"=?' for key in keys)
                    self.execute(db, f"DELETE FROM {self.name(table)}{scope} AND {where}", (*scope_args, *change.key))
                else:
                    names = columns[table]
                    values = [change.data[name] for name in names]
                    if not self.sqlite:
                        from psycopg.types.json import Jsonb

                        values = [
                            Jsonb(json.loads(value))
                            if name in JSON_COLUMNS and value is not None
                            else bool(value)
                            if name == "dirty"
                            else value
                            for name, value in zip(names, values, strict=True)
                        ]
                        names, values = ["namespace", *names], [self.ns, *values]
                    quoted = ",".join(f'"{n}"' for n in names)
                    conflict = ",".join((["namespace"] if not self.sqlite else []) + list(keys))
                    updates = ",".join(f'"{n}"=excluded."{n}"' for n in names if n not in {*keys, "namespace"})
                    self.execute(
                        db,
                        f"INSERT INTO {self.name(table)} ({quoted}) VALUES ({','.join('?' for _ in names)}) "
                        f"ON CONFLICT({conflict}) DO UPDATE SET {updates}",
                        values,
                    )
            if self.sqlite:
                for name in ("memory", "raw_events", "candidates", "atoms", "episodes"):
                    table = self.name(name + "_fts")
                    self.execute(db, f"INSERT INTO {table}({table}) VALUES ('rebuild')")


__all__ = ["LogicalSync"]
